int hod2_character_clip(unsigned int version,unsigned int type,
                        unsigned int which,unsigned int *id,
                        unsigned int *provenance) {
 const Hod2ClipRow *r;
 if(version>1U || type>=HOD2_CHARACTER_TYPES || !id || !provenance) return 0;
 r=(version==0U ? hod2_clips_y99 : hod2_clips_y2000)+type;
 *provenance=r->provenance;
 if(which>=r->count) { *id=0U;return 0; }
 *id=(which==0U ? r->clip0 : r->clip1);
 return 1;
}
